os.makedirs(BASE, exist_ok=True)
for cid in IDS:
    assert cid in DATA, cid
    with open(os.path.join(BASE, cid+".json"),"w",encoding="utf-8") as f:
        json.dump(DATA[cid], f, ensure_ascii=False, indent=1)
# verify by exact re-open per id
n=0; trig={"changed_main":0,"reserve_used":0,"disputed":0}
for cid in IDS:
    with open(os.path.join(BASE, cid+".json"),encoding="utf-8") as f:
        d=json.load(f)
    assert d["case_id"]==cid and d["prediction_text"] and d["basis"] and isinstance(d["confidence"],(int,float)) and "systems_used" in d["basis"]
    for k in trig:
        assert isinstance(d["trigger"][k], bool)
        trig[k]+=int(d["trigger"][k])
    assert isinstance(d["trigger"]["reason"], str)
    n+=1
print("written_and_verified", n, trig)
